import http from 'node:http';
import { readFile, mkdir, rename, writeFile } from 'node:fs/promises';
import { randomUUID } from 'node:crypto';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.dirname(fileURLToPath(import.meta.url));
const defaultBooksFile = path.join(root, 'data', 'books.json');
const publicFiles = new Map([
  ['/styles.css', ['styles.css', 'text/css; charset=utf-8']],
  ['/app.js', ['app.js', 'text/javascript; charset=utf-8']],
  ['/favicon.svg', ['favicon.svg', 'image/svg+xml']],
]);

class HttpError extends Error {
  constructor(status, message) {
    super(message);
    this.status = status;
  }
}

function json(res, status, value) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' });
  res.end(JSON.stringify(value));
}

async function readBooks(booksFile) {
  try {
    const books = JSON.parse(await readFile(booksFile, 'utf8'));
    if (!Array.isArray(books)) throw new Error('Books file must contain an array');
    return books;
  } catch (error) {
    if (error.code === 'ENOENT') return [];
    throw error;
  }
}

async function saveBooks(booksFile, books) {
  await mkdir(path.dirname(booksFile), { recursive: true });
  const temporaryFile = `${booksFile}.${randomUUID()}.tmp`;
  try {
    await writeFile(temporaryFile, `${JSON.stringify(books, null, 2)}\n`, { flag: 'wx' });
    await rename(temporaryFile, booksFile);
  } catch (error) {
    // A failed write never replaces the last good copy of the library.
    const { unlink } = await import('node:fs/promises');
    await unlink(temporaryFile).catch(() => {});
    throw error;
  }
}

async function parseBody(req) {
  let body = '';
  for await (const chunk of req) {
    body += chunk;
    if (Buffer.byteLength(body) > 32_768) throw new HttpError(413, 'Request is too large.');
  }
  try {
    const value = JSON.parse(body);
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('Invalid object');
    return value;
  } catch {
    throw new HttpError(400, 'Please send a valid JSON object.');
  }
}

function requiredText(value, label, maxLength) {
  if (typeof value !== 'string' || !value.trim()) throw new HttpError(400, `${label} is required.`);
  const result = value.trim();
  if (result.length > maxLength) throw new HttpError(400, `${label} must be ${maxLength} characters or fewer.`);
  return result;
}

function notesText(value) {
  if (typeof value !== 'string' || value.length > 5000) {
    throw new HttpError(400, 'Notes must be text of 5000 characters or fewer.');
  }
  return value.trim();
}

export function createServer({ booksFile = process.env.BOOKS_FILE || defaultBooksFile } = {}) {
  let mutationQueue = Promise.resolve();
  const mutate = (operation) => {
    const next = mutationQueue.then(async () => {
      const books = await readBooks(booksFile);
      const result = operation(books);
      await saveBooks(booksFile, books);
      return result;
    });
    mutationQueue = next.catch(() => {});
    return next;
  };

  return http.createServer(async (req, res) => {
    try {
      const pathname = new URL(req.url, 'http://localhost').pathname;
      if (pathname === '/api/books' && req.method === 'GET') {
        return json(res, 200, await readBooks(booksFile));
      }
      if (pathname === '/api/books' && req.method === 'POST') {
        const input = await parseBody(req);
        const title = requiredText(input.title, 'Title', 160);
        const author = requiredText(input.author, 'Author', 120);
        const notes = notesText(input.notes ?? '');
        if (input.status !== undefined && !['reading', 'finished'].includes(input.status)) {
          throw new HttpError(400, 'Invalid reading status.');
        }
        const book = await mutate((books) => {
          const now = new Date().toISOString();
          const item = { id: randomUUID(), title, author, notes, status: input.status || 'reading', createdAt: now, finishedAt: input.status === 'finished' ? now : null };
          books.push(item);
          return item;
        });
        return json(res, 201, book);
      }
      const bookId = pathname.match(/^\/api\/books\/([0-9a-f-]+)$/)?.[1];
      if (bookId && req.method === 'GET') {
        const book = (await readBooks(booksFile)).find((item) => item.id === bookId);
        if (!book) throw new HttpError(404, 'Book not found.');
        return json(res, 200, book);
      }
      if (bookId && req.method === 'PATCH') {
        const input = await parseBody(req);
        if (!Object.hasOwn(input, 'status') && !Object.hasOwn(input, 'notes')) {
          throw new HttpError(400, 'Nothing to update.');
        }
        if (Object.hasOwn(input, 'status') && !['reading', 'finished'].includes(input.status)) {
          throw new HttpError(400, 'Invalid reading status.');
        }
        const notes = Object.hasOwn(input, 'notes') ? notesText(input.notes) : undefined;
        const book = await mutate((books) => {
          const item = books.find((entry) => entry.id === bookId);
          if (!item) throw new HttpError(404, 'Book not found.');
          if (input.status !== undefined && item.status !== input.status) {
            item.status = input.status;
            item.finishedAt = input.status === 'finished' ? new Date().toISOString() : null;
          }
          if (notes !== undefined) item.notes = notes;
          return item;
        });
        return json(res, 200, book);
      }
      if (req.method === 'GET') {
        if (publicFiles.has(pathname)) {
          const [file, contentType] = publicFiles.get(pathname);
          res.writeHead(200, { 'Content-Type': contentType });
          return res.end(await readFile(path.join(root, 'public', file)));
        }
        if (pathname === '/' || /^\/books\/[0-9a-f-]+\/?$/.test(pathname)) {
          res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
          return res.end(await readFile(path.join(root, 'public', 'index.html')));
        }
      }
      throw new HttpError(404, 'Page not found.');
    } catch (error) {
      if (!error.status) console.error(error);
      if (!res.headersSent) json(res, error.status || 500, { error: error.status ? error.message : 'Could not access the library.' });
      else res.end();
    }
  });
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const port = Number(process.env.PORT || 3000);
  createServer().listen(port, '0.0.0.0', () => console.log(`Margin is running at http://localhost:${port}`));
}

