args.content:
const view = document.querySelector('#view');
const dialog = document.querySelector('#book-dialog');
const bookForm = document.querySelector('#book-form');
const toast = document.querySelector('#toast');
document.querySelector('#year').textContent = new Date().getFullYear();

const icon = {
  arrow: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg>',
  book: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 6.5c-3.2-2-6.7-2.2-9-1v13c3.2-1 6.2-.5 9 1.3 2.8-1.8 5.8-2.3 9-1.3v-13c-2.3-1.2-5.8-1-9 1Z"/><path d="M12 6.5v13.3"/></svg>',
  check: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="m8 12 2.7 2.7L16.5 9"/></svg>',
  link: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M10 13a5 5 0 0 0 7.5.5l2-2a5 5 0 0 0-7-7l-1.1 1.1M14 11a5 5 0 0 0-7.5-.5l-2 2a5 5 0 0 0 7 7l1.1-1.1"/></svg>',
};

function escapeHTML(value) {
  return String(value).replace(/[&<>"']/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[character]);
}

async function request(url, options) {
  const response = await fetch(url, options);
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || 'Something went wrong.');
  return data;
}

function updateCounts(books) {
  document.querySelector('#nav-reading').textContent = books.filter((book) => book.status === 'reading').length;
  document.querySelector('#nav-finished').textContent = books.filter((book) => book.status === 'finished').length;
}

function colorFor(id) {
  const colors = ['olive', 'clay', 'blue', 'plum', 'ochre', 'pine'];
  const hash = [...id].reduce((total, char) => total + char.charCodeAt(0), 0);
  return colors[hash % colors.length];
}

function cover(book, large = false) {
  return `<div class="book-cover cover--${colorFor(book.id)}${large ? ' book-cover--large' : ''}" aria-hidden="true">
    <div class="cover-top">MARGIN <span>✳</span></div>
    <div class="cover-middle"><span class="cover-rule"></span><span class="cover-title">${escapeHTML(book.title)}</span><span class="cover-author">${escapeHTML(book.author)}</span></div>
    <span class="cover-bottom">A READING JOURNAL</span>
  </div>`;
}

function bookCard(book) {
  return `<article class="book-card">
    <a class="book-card-link" href="/books/${book.id}" aria-label="View ${escapeHTML(book.title)} by ${escapeHTML(book.author)}">
      ${cover(book)}
      <div class="book-card-info"><span class="card-kicker">${book.status === 'reading' ? 'ON YOUR NIGHTSTAND' : 'ON THE SHELF'}</span><h3>${escapeHTML(book.title)}</h3><p>by ${escapeHTML(book.author)}</p><span class="card-open">View book ${icon.arrow}</span></div>
    </a>
    ${book.status === 'reading' ? `<button type="button" class="card-finish" data-action="finish" data-id="${book.id}" aria-label="Mark ${escapeHTML(book.title)} as finished" title="Mark as finished">${icon.check}</button>` : `<span class="card-finished" title="Finished">${icon.check}</span>`}
  </article>`;
}

function emptyState(type) {
  const reading = type === 'reading';
  return `<div class="empty-state"><div class="empty-icon">${reading ? icon.book : icon.check}</div><h3>${reading ? 'A fresh page awaits.' : 'Your finished shelf starts here.'}</h3><p>${reading ? 'Add the book you’re reading now and make this little corner yours.' : 'The books you finish will find a home here.'}</p>${reading ? '<button type="button" class="text-button" data-action="add">Add your first book <span aria-hidden="true">↗</span></button>' : ''}</div>`;
}

function section(type, books) {
  const reading = type === 'reading';
  const matching = books.filter((book) => book.status === type).sort((a, b) => (reading ? b.createdAt.localeCompare(a.createdAt) : (b.finishedAt || '').localeCompare(a.finishedAt || '')));
  return `<section class="shelf-section" id="${type}" aria-labelledby="${type}-title">
    <div class="section-heading"><div><p class="eyebrow">${reading ? 'IN THE MOMENT' : 'THE GOOD ONES STAY'}</p><h2 id="${type}-title">${reading ? 'Currently reading' : 'Finished'} <span class="section-count">${matching.length}</span></h2></div><span class="section-decoration" aria-hidden="true">${reading ? '01' : '02'}</span></div>
    <div class="section-body">${matching.length ? `<div class="book-list">${matching.map(bookCard).join('')}</div>` : emptyState(type)}</div>
  </section>`;
}

async function loadHome() {
  const books = await request('/api/books');
  updateCounts(books);
  document.title = 'Margin — Your reading shelf';
  const reading = books.filter((book) => book.status === 'reading').length;
  const finished = books.length - reading;
  view.innerHTML = `<div class="home-page">
    <div class="page-intro"><div><p class="eyebrow"><span class="eyebrow-line"></span> YOUR PERSONAL LIBRARY</p><h1>Between the <em>lines.</em></h1><p class="intro-subtitle">A little space for every book you pick up, put down, and carry with you.</p></div><span class="intro-flourish" aria-hidden="true">✳</span></div>
    <div class="dashboard">
      <div class="welcome-card"><div class="welcome-content"><span class="welcome-label"><span class="tiny-star">✳</span> THE READING LIFE</span><h2>Good stories deserve<br>a place to <em>stay.</em></h2><p>Keep track of the pages you're turning and the thoughts worth remembering.</p><button type="button" class="button button--cream" data-action="add">Add a book <span aria-hidden="true">↗</span></button></div><div class="book-art" aria-hidden="true"><div class="art-orbit"></div><div class="art-spark art-spark--one">✳</div><div class="art-spark art-spark--two">✦</div><div class="art-book art-book--back"><span>NOTES<br>ON THE<br>MARGINS</span></div><div class="art-book art-book--front"><span class="art-rule"></span><span>THE<br>STORY<br>GOES ON</span><small>✳</small></div></div></div>
      <div class="stats-card"><div class="stats-top"><span class="eyebrow">AT A GLANCE</span><span class="stats-icon" aria-hidden="true">✳</span></div><p class="stats-heading">Your shelf, your story.</p><div class="stats-row"><div><strong>${reading}</strong><span>Reading now</span></div><span class="stats-row-icon">${icon.book}</span></div><div class="stats-row"><div><strong>${finished}</strong><span>Books finished</span></div><span class="stats-row-icon">${icon.check}</span></div><div class="stats-foot">One page at a time <span aria-hidden="true">↗</span></div></div>
    </div>
    <div class="shelves"><div class="shelves-title"><span class="eyebrow">THE COLLECTION</span><span class="shelves-line"></span><span class="shelves-total">${books.length} ${books.length === 1 ? 'BOOK' : 'BOOKS'} & COUNTING</span></div><div class="shelves-grid">${section('reading', books)}${section('finished', books)}</div></div>
  </div>`;
  if (location.hash === '#reading' || location.hash === '#finished') {
    requestAnimationFrame(() => document.querySelector(location.hash)?.scrollIntoView());
  }
}

function detailMarkup(book) {
  const finished = book.status === 'finished';
  return `<div class="detail-page">
    <div class="detail-breadcrumb"><a href="/">My library</a><span aria-hidden="true">/</span><span>${escapeHTML(book.title)}</span></div>
    <a class="back-link" href="/"><span aria-hidden="true">←</span> Back to library</a>
    <div class="detail-hero"><div class="detail-cover-area"><div class="detail-cover-halo"></div>${cover(book, true)}<span class="detail-cover-caption">A BOOK WORTH REMEMBERING</span></div>
      <div class="detail-info"><p class="eyebrow"><span class="eyebrow-line"></span> ${finished ? 'FROM YOUR FINISHED SHELF' : 'CURRENTLY ON YOUR NIGHTSTAND'}</p><h1>${escapeHTML(book.title)}</h1><p class="detail-author">by <strong>${escapeHTML(book.author)}</strong></p><div class="detail-divider"></div><span class="status-pill ${finished ? 'status-pill--finished' : ''}"><span class="status-dot"></span>${finished ? 'Finished' : 'Currently reading'}</span><p class="detail-meta">${finished ? `Finished ${formatDate(book.finishedAt)}` : `Added ${formatDate(book.createdAt)}`}</p><div class="detail-actions"><button class="button button--primary" type="button" data-action="toggle-status" data-id="${book.id}" data-status="${finished ? 'reading' : 'finished'}">${finished ? 'Move to reading' : `${icon.check} Mark as finished`}</button><button class="button button--outline" type="button" data-action="share">${icon.link} Copy book link</button></div></div></div>
    <section class="notes-section" aria-labelledby="notes-title"><div class="notes-heading"><div><p class="eyebrow">THOUGHTS TO KEEP</p><h2 id="notes-title">In the margins<span class="accent-dot">.</span></h2></div><button class="text-button" type="button" data-action="edit-notes">${book.notes ? 'Edit notes' : 'Add notes'} <span aria-hidden="true">↗</span></button></div>
      <div class="notes-content" id="notes-display">${book.notes ? `<p class="note-text">${escapeHTML(book.notes)}</p>` : `<div class="notes-empty"><span aria-hidden="true">✳</span><p>No notes yet. A thought, a favorite line, a feeling — save it here.</p></div>`}</div>
      <form class="notes-editor" id="notes-form" data-id="${book.id}" hidden><label for="detail-notes">Your notes</label><textarea id="detail-notes" name="notes" rows="6" maxlength="5000" placeholder="What stayed with you?">${escapeHTML(book.notes)}</textarea><p class="form-error" id="notes-error" role="alert" hidden></p><div class="notes-form-actions"><button class="button button--subtle" type="button" data-action="cancel-notes">Cancel</button><button class="button button--primary" type="submit">Save notes</button></div></form>
    </section><div class="detail-bottom"><span>Every story leaves a mark.</span><a href="/">Explore your library ${icon.arrow}</a></div>
  </div>`;
}

function formatDate(value) {
  if (!value) return 'recently';
  return new Intl.DateTimeFormat('en', { month: 'long', day: 'numeric', year: 'numeric' }).format(new Date(value));
}

async function loadDetail(id) {
  const [book, books] = await Promise.all([request(`/api/books/${id}`), request('/api/books')]);
  updateCounts(books);
  document.title = `${book.title} — Margin`;
  view.innerHTML = detailMarkup(book);
}

function showToast(message) {
  toast.textContent = message;
  toast.classList.add('toast--visible');
  clearTimeout(showToast.timer);
  showToast.timer = setTimeout(() => toast.classList.remove('toast--visible'), 3500);
}

function showError(error) {
  view.innerHTML = `<div class="error-page"><span aria-hidden="true">✳</span><h1>We lost our place.</h1><p>${escapeHTML(error.message)}</p><a class="button button--primary" href="/">Back to library</a></div>`;
}

async function init() {
  try {
    const match = location.pathname.match(/^\/books\/([0-9a-f-]+)\/?$/);
    if (match) await loadDetail(match[1]);
    else await loadHome();
  } catch (error) {
    showError(error);
  }
}

function openDialog() {
  bookForm.reset();
  document.querySelector('#form-error').hidden = true;
  dialog.showModal();
  document.querySelector('#book-title').focus();
}

document.addEventListener('click', async (event) => {
  const button = event.target.closest('[data-action]');
  if (!button) return;
  const action = button.dataset.action;
  if (action === 'add') return openDialog();
  if (action === 'close-dialog') return dialog.close();
  if (action === 'edit-notes' || action === 'cancel-notes') {
    document.querySelector('#notes-display').hidden = action === 'edit-notes';
    document.querySelector('#notes-form').hidden = action !== 'edit-notes';
    if (action === 'edit-notes') document.querySelector('#detail-notes').focus();
    return;
  }
  if (action === 'share') {
