import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { once } from 'node:events';
import { createServer } from '../server.js';

async function start(booksFile) {
  const server = createServer({ booksFile });
  server.listen(0, '127.0.0.1');
  await once(server, 'listening');
  return { server, base: `http://127.0.0.1:${server.address().port}` };
}

async function call(base, route, method = 'GET', body) {
  const response = await fetch(base + route, {
    method,
    headers: body ? { 'Content-Type': 'application/json' } : {},
    body: body ? JSON.stringify(body) : undefined,
  });
  return { status: response.status, data: await response.json() };
}

test('books are added, updated, shareable, and persisted through a server restart', async (t) => {
  const dir = await mkdtemp(path.join(tmpdir(), 'margin-test-'));
  const booksFile = path.join(dir, 'books.json');
  t.after(() => rm(dir, { recursive: true, force: true }));
  let { server, base } = await start(booksFile);
  t.after(() => server.close());

  assert.deepEqual((await call(base, '/api/books')).data, []);
  const created = await call(base, '/api/books', 'POST', { title: '  The Left Hand of Darkness  ', author: ' Ursula K. Le Guin ', notes: 'A first thought.' });
  assert.equal(created.status, 201);
  assert.equal(created.data.title, 'The Left Hand of Darkness');
  assert.equal(created.data.author, 'Ursula K. Le Guin');
  assert.equal(created.data.status, 'reading');
  assert.equal(created.data.finishedAt, null);
  const id = created.data.id;
  assert.match(id, /^[0-9a-f-]{36}$/);
  assert.equal((await call(base, `/api/books/${id}`)).data.notes, 'A first thought.');
  const detail = await fetch(`${base}/books/${id}`);
  assert.equal(detail.status, 200);
  assert.match(await detail.text(), /<script type="module" src="\/app.js"><\/script>/);

  const updated = await call(base, `/api/books/${id}`, 'PATCH', { status: 'finished', notes: 'A lasting thought.\nWonderful.' });
  assert.equal(updated.status, 200);
  assert.equal(updated.data.status, 'finished');
  assert.ok(updated.data.finishedAt);
  assert.equal(updated.data.notes, 'A lasting thought.\nWonderful.');
  assert.equal(JSON.parse(await readFile(booksFile, 'utf8'))[0].status, 'finished');

  await new Promise((resolve, reject) => server.close((error) => error ? reject(error) : resolve()));
  ({ server, base } = await start(booksFile));
  assert.equal((await call(base, '/api/books')).data[0].notes, 'A lasting thought.\nWonderful.');
  const readingAgain = await call(base, `/api/books/${id}`, 'PATCH', { status: 'reading' });
  assert.equal(readingAgain.data.finishedAt, null);
});

test('validation, missing books, and concurrent writes keep the library intact', async (t) => {
  const dir = await mkdtemp(path.join(tmpdir(), 'margin-test-'));
  const booksFile = path.join(dir, 'nested', 'books.json');
  const { server, base } = await start(booksFile);
  t.after(() => server.close());
  t.after(() => rm(dir, { recursive: true, force: true }));

  assert.equal((await call(base, '/api/books', 'POST', { title: ' ', author: 'Someone' })).status, 400);
  assert.equal((await call(base, '/api/books', 'POST', { title: 'Book', author: 'Someone', status: 'unknown' })).status, 400);
  assert.equal((await call(base, '/api/books/no-such-book')).status, 404);
  const added = await Promise.all(Array.from({ length: 8 }, (_, i) => call(base, '/api/books', 'POST', { title: `Book ${i}`, author: 'Someone' })));
  assert.ok(added.every(({ status }) => status === 201));
  assert.equal((await call(base, '/api/books')).data.length, 8);
  assert.equal((await call(base, `/api/books/${added[0].data.id}`, 'PATCH', { notes: 123 })).status, 400);
  assert.equal((await call(base, `/api/books/${added[0].data.id}`, 'PATCH', { status: 'finished' })).status, 200);
  assert.equal(JSON.parse(await readFile(booksFile, 'utf8')).length, 8);
});

